import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv3d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_depth,
    int input_height,
    int input_width,
    int kernel_size,
    int output_depth,
    int output_height,
    int output_width,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * output_depth * output_height * output_width;
    if (idx >= total_elements) return;

    int elements_per_batch = out_channels * output_depth * output_height * output_width;
    int n = idx / elements_per_batch;
    int remainder = idx % elements_per_batch;

    int elements_per_channel = output_depth * output_height * output_width;
    int oc = remainder / elements_per_channel;
    remainder %= elements_per_channel;

    int od = remainder / (output_height * output_width);
    remainder %= (output_height * output_width);
    int oh = remainder / output_width;
    int ow = remainder % output_width;

    float sum = 0.0f;
    int group_size = out_channels / groups;
    int g = oc / group_size;
    int in_channels_per_group = in_channels / groups;
    int start_ic = g * in_channels_per_group;

    for (int ic = start_ic; ic < start_ic + in_channels_per_group; ++ic) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            int id = od * stride - padding + kd * dilation;
            if (id < 0 || id >= input_depth) continue;
            for (int kh = 0; kh < kernel_size; ++kh) {
                int ih = oh * stride - padding + kh * dilation;
                if (ih < 0 || ih >= input_height) continue;
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int iw = ow * stride - padding + kw * dilation;
                    if (iw < 0 || iw >= input_width) continue;

                    int input_idx = n * in_channels * input_depth * input_height * input_width
                                  + ic * input_depth * input_height * input_width
                                  + id * input_height * input_width
                                  + ih * input_width
                                  + iw;

                    int weight_idx = oc * (in_channels_per_group * kernel_size * kernel_size * kernel_size)
                                   + (ic - start_ic) * kernel_size * kernel_size * kernel_size
                                   + kd * kernel_size * kernel_size
                                   + kh * kernel_size
                                   + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (has_bias) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups
) {
    TORCH_CHECK(input.dim() == 5, "Input must be 5D");
    TORCH_CHECK(weight.dim() == 5, "Weight must be 5D");

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int output_depth = (input_depth + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_height = (input_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_width = (input_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, output_depth, output_height, output_width}, input.options());
    int total_elements = output.numel();

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    bool has_bias = bias.defined() && bias.numel() > 0;
    conv3d_kernel<<<grid_size, block_size>>>(
        input.contiguous().data_ptr<float>(),
        weight.contiguous().data_ptr<float>(),
        has_bias ? bias.contiguous().data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_depth,
        input_height,
        input_width,
        kernel_size,
        output_depth,
        output_height,
        output_width,
        stride,
        padding,
        dilation,
        groups,
        has_bias
    );

    return output;
}
"""

conv3d_cpp_source = "torch::Tensor conv3d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, int dilation, int groups);"

conv3d_ext = load_inline(
    name='conv3d_ext',
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=['conv3d_forward_cuda'],
    verbose=False
)

class CustomConv3d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride=1, padding=0, dilation=1, groups=1, bias=False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return conv3d_ext.conv3d_forward_cuda(
            x, self.weight, self.bias if self.bias is not None else torch.Tensor(),
            self.stride, self.padding, self.dilation, self.groups
        )

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv3d = CustomConv3d(in_channels, out_channels, kernel_size, stride, padding, dilation, groups, bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv3d(x)
